import re
from collections import defaultdict
from typing import Dict, List, Tuple

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: Dict[str, Dict[str, str]] = defaultdict(dict)
    current_section: str = "DEFAULT"
    lines = text.splitlines()
    i = 0
    default_section = {}

    def process_line(line: str) -> None:
        nonlocal current_section
        stripped = line.strip()
        if not stripped or stripped[0] in ';#':
            return

        if stripped.startswith('[') and stripped.endswith(']'):
            section_name = stripped[1:-1].strip()
            if not section_name:
                raise ValueError("Empty section name")
            current_section = section_name
            if current_section not in sections:
                sections[current_section] = {}
            return

        if '=' in line or ':' in line:
            key_end = -1
            for sep in ['=', ':']:
                pos = line.find(sep)
                if pos != -1:
                    if key_end == -1 or pos < key_end:
                        key_end = pos
            if key_end == -1:
                raise ValueError("Malformed line")

            key = line[:key_end].strip().lower()
            if not key:
                raise ValueError("Empty key")

            value_part = line[key_end + 1:]
            comment_pos = -1
            for pattern in [' ;', ' #']:
                pos = value_part.find(pattern)
                if pos != -1:
                    if comment_pos == -1 or pos < comment_pos:
                        comment_pos = pos
            if comment_pos != -1:
                value_part = value_part[:comment_pos]

            if value_part.startswith('"') and value_part.endswith('"'):
                value = value_part[1:-1]
            else:
                value = value_part.strip()

            if current_section == "DEFAULT":
                default_section[key] = value
            else:
                sections[current_section][key] = value
            return

        if line[0].isspace():
            if not sections[current_section]:
                raise ValueError("Continuation line without preceding key")
            last_key = next(reversed(sections[current_section]))
            sections[current_section][last_key] += '\n' + line.strip()
            return

        raise ValueError("Malformed line")

    for line in lines:
        process_line(line)

    result = {}
    for section, kvs in sections.items():
        if section == "DEFAULT":
            continue
        inherited = default_section.copy()
        inherited.update(kvs)
        result[section] = inherited

    def interpolate(value: str, section: str, visited: set) -> str:
        def replace_match(match):
            ref = match.group(1)
            if ':' in ref:
                s, k = ref.split(':', 1)
                if s not in result:
                    raise KeyError(f"Section {s} not found")
                if k not in result[s]:
                    raise KeyError(f"Key {k} not found in section {s}")
                ref_value = result[s][k]
            else:
                k = ref
                if k in result[section]:
                    ref_value = result[section][k]
                elif k in default_section:
                    ref_value = default_section[k]
                else:
                    raise KeyError(f"Key {k} not found")
            if ref_value in visited:
                raise ValueError("Interpolation cycle detected")
            visited.add(ref_value)
            return interpolate(ref_value, section, visited)
        pattern = re.compile(r'\$\{([^}]+)\}')
        while True:
            new_value = pattern.sub(replace_match, value)
            if new_value == value:
                break
            value = new_value
        return value

    final_result = {}
    for section, kvs in result.items():
        final_kvs = {}
        for key, value in kvs.items():
            final_kvs[key] = interpolate(value, section, set())
        final_result[section] = final_kvs

    return final_result
