import re

def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("Empty or blank string")

    pattern = re.compile(
        r'^\s*'
        r'(?:(?P<hours>\d+)\s*h\s*)?'
        r'(?:(?P<minutes>\d+)\s*m\s*)?'
        r'(?:(?P<seconds>\d+)\s*s\s*)?'
        r'\s*$',
        flags=re.IGNORECASE
    )

    match = pattern.fullmatch(s)
    if not match:
        raise ValueError("Invalid duration format")

    groups = match.groupdict()
    if not any(groups.values()):
        raise ValueError("No duration components found")

    hours = int(groups['hours']) if groups['hours'] is not None else 0
    minutes = int(groups['minutes']) if groups['minutes'] is not None else 0
    seconds = int(groups['seconds']) if groups['seconds'] is not None else 0

    if groups['hours'] is not None and groups['minutes'] is not None and groups['seconds'] is not None:
        pass
    elif groups['hours'] is not None and groups['minutes'] is not None:
        pass
    elif groups['hours'] is not None and groups['seconds'] is not None:
        raise ValueError("Units out of order: minutes missing between hours and seconds")
    elif groups['minutes'] is not None and groups['seconds'] is not None:
        pass
    elif groups['hours'] is not None:
        pass
    elif groups['minutes'] is not None:
        pass
    elif groups['seconds'] is not None:
        pass

    return hours * 3600 + minutes * 60 + seconds
