import re
from collections import defaultdict

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_totals = defaultdict(float)
    customer_names = {}

    amount_pattern = re.compile(r'^[+-]?\$?[\d,]+\.?\d*$')

    for row in rows:
        customer = row.get("customer", "").strip()
        amount_str = row.get("amount", "")

        if not customer or not amount_str or not amount_pattern.match(amount_str):
            continue

        try:
            amount = float(amount_str.replace("$", "").replace(",", ""))
        except ValueError:
            continue

        if customer not in customer_names:
            customer_names[customer] = customer

        customer_totals[customer] += amount

    sorted_customers = sorted(
        customer_totals.items(),
        key=lambda item: (-item[1], item[0])
    )

    return sorted_customers[:n]
